const a={back:"Atrás",continue:"Continuar",step_of:"{current} de {total}",welcome:{title:"Bienvenido",lede:"Primero, un vistazo rápido a qué es {name} y cómo funciona. Después lo configuramos aquí mismo, en la aplicación: una clave de API, una suscripción para tus agentes y tu palabra de activación.",language:"Idioma",lang_en:"English",lang_de:"Deutsch",lang_es:"Español",start:"Empezar"},how:{title:"Cómo funciona {name}",lede:"Un asistente con el que hablas. Detrás: un cerebro, herramientas, un equipo de agentes y una memoria.",next:"Siguiente",prev:"Atrás",skip:"Saltar la explicación",finish:"Entendido, a configurarlo",chapter_of:"{current} / {total}",chapters_label:"Capítulos",map_label:"Cómo se conectan las partes de tu asistente",journey_pick:"Elige una petición de ejemplo",journey_replay:"Reproducir de nuevo",nodes:{center:"{name}",you:"Tú",you_sub:"Voz, chat, móvil",brain:"Cerebro",brain_sub:"El modelo de IA",tools:"Herramientas",tools_sub:"Ordenador, apps, web",agents:"Agentes",agents_sub:"Equipo para lo grande",memory:"Memoria",memory_sub:"Wiki y perfil",results:"Resultados",results_sub:"Respuestas y archivos",safety:"Control de seguridad"},chapters:{intro:{title:"Un asistente para todo",say:"¡Hola, soy Gigi! {name} no es un chatbot más. Es UN asistente que trabaja para ti en tu ordenador. Solo hablas con {name}: decide qué hay que hacer y quién lo hace.",p1:"Sin saltar entre apps ni herramientas de IA. Dices lo que quieres, una vez.",p2:"{name} piensa, usa tu ordenador y tus apps, y pasa los trabajos grandes a agentes ayudantes.",p3:"Todo vuelve a ti en un solo lugar: en voz alta, en el chat o como archivo terminado."},you:{title:"Háblale como quieras",say:"Habla, escribe o escríbele desde el móvil. Cada camino lleva al mismo {name}, con la misma memoria.",p1:"Voz: di tu palabra de activación o pulsa el atajo de llamada y habla. {name} responde en voz alta.",p2:"Chat: escribe en la aplicación. Cada conversación se guarda en Chats recientes.",p3:"Fuera de casa: conecta Telegram y escribe a {name} desde el móvil. El dictado escribe lo que dices en cualquier otra app."},brain:{title:"El cerebro: un modelo de IA que eliges tú",say:"Para pensar, {name} usa un modelo de IA: de OpenAI, Google Gemini, Anthropic Claude, OpenRouter y otros, o uno que funciona en tu propio ordenador. Tú decides.",p1:"Basta con una clave. La añades en el siguiente paso y puedes cambiar de modelo cuando quieras.",p2:"Para los agentes, una suscripción que ya pagas (Claude o ChatGPT) evita pagar por cada llamada.",p3:"Si un proveedor falla, {name} pasa a otro que hayas conectado en vez de detenerse."},tools:{title:"Herramientas: sus manos",say:"Las tareas pequeñas las hace {name} solo, al momento, mientras habláis. Eso son las herramientas: sus manos en tu ordenador y en tus apps.",p1:"Tu ordenador: abrir apps y webs, hacer clic y escribir en pantalla, mirar tu pantalla, leer y escribir archivos, ejecutar comandos.",p2:"Tus apps y servicios: correo, calendario, hogar inteligente y más, conectados como Plugins o MCP desde el Marketplace.",p3:"Skills: enséñale una rutina una vez y la repetirá cuando se lo pidas."},agents:{title:"Agentes: un equipo para los trabajos grandes",say:"Cuando un trabajo lleva más tiempo, como una investigación, un informe, una web o código, {name} se lo pasa a un agente. Tú sigues hablando; el agente trabaja en segundo plano.",p1:"Los agentes viven en el área Agentes. Míralos trabajar, chatea con uno o dale un encargo directamente.",p2:"Un revisor comprueba el trabajo del agente antes de que el resultado te llegue.",p3:"Agentes de programación como Claude Code y Codex trabajan lado a lado en el Agentic IDE, en tus propios proyectos. Los agentes también pueden ejecutar rutinas programadas."},memory:{title:"Memoria: te va conociendo",say:"{name} recuerda lo importante: lo que le contaste, lo que te gusta, las personas y proyectos de tu vida.",p1:"La Wiki guarda notas que {name} puede leer, escribir y citar. Puedes abrir y editar cada página.",p2:"Tu perfil reúne lo que sabe de ti, para que nunca tengas que repetirte.",p3:"Chats, notas y archivos se guardan en tu ordenador. Solo lo que un modelo necesita para responder va al proveedor que elegiste."},safety:{title:"Tú mantienes el control",say:"Antes de que {name} haga algo, un control de seguridad lo revisa. Lo inofensivo simplemente ocurre. Todo lo que tiene consecuencias reales espera tu sí.",p1:"Cuatro niveles: seguro (se ejecuta), vigilado (se ejecuta y se registra), preguntar (espera tu OK), bloqueado (nunca se ejecuta).",p2:"Enviar un correo, borrar archivos o hacer una llamada te pregunta antes y te muestra exactamente qué pasará.",p3:"Las claves se quedan en el llavero de tu sistema. Nunca digas ni escribas una clave en el chat: {name} no la acepta ahí."},journey:{title:"Pruébalo: sigue una petición",say:"Elige una petición abajo y mira por dónde viaja dentro de {name}."},app:{title:"Dónde lo encuentras en la aplicación",say:"Todo lo que acabas de ver tiene su sitio en la barra lateral izquierda. Ahora configuramos juntos el cerebro; tarda unos dos minutos."}},journeys:{e1:{label:"¿Qué tengo mañana en el calendario?",s1:"Preguntas por voz.",s2:"Te escucha y entiende lo que quieres.",s3:"Decide: esto necesita tu calendario.",s4:"Lee tu calendario a través de la app conectada, una llamada rápida a una herramienta.",s5:"La respuesta se dice en voz alta en pocos segundos."},e2:{label:"Haz una web para mi panadería",s1:"Lo pides en el chat.",s2:"Ve un trabajo grande.",s3:"Planifica el trabajo y elige al ayudante adecuado.",s4:"Un agente construye la página en segundo plano mientras sigues hablando; un revisor la comprueba.",s5:"La página terminada aparece en Artifacts y en tu chat."},e3:{label:"Recuerda: el cumpleaños de Anna es el 3 de mayo",s1:"Lo mencionas de pasada.",s2:"Nota que vale la pena guardarlo.",s3:"Lo escribe en la Wiki, en la página de Anna.",s4:"La próxima vez que preguntes por Anna, {name} lo sabrá."},e4:{label:"Escribe al equipo que llego tarde",s1:"Lo dices al salir.",s2:"Entiende: un correo a tu equipo.",s3:"Redacta el correo.",s4:"Enviar es una acción real, así que {name} te muestra el correo y espera tu sí.",s5:"Solo tras tu OK lo envía con tu correo conectado.",s6:"{name} confirma que se ha enviado."}},app:{chats:"Chats",chats_sub:"Habla y escribe con {name}; cada conversación se guarda.",agents:"Agentes",agents_sub:"Tu equipo trabajando: crea agentes, dales encargos, obsérvalos.",voice:"Voz",voice_sub:"Dictado en cualquier app, tu lista de palabras, atajos por voz.",artifacts:"Artifacts",artifacts_sub:"Páginas, imágenes e informes que {name} hizo para ti.",ide:"Agentic IDE",ide_sub:"Agentes de programación en terminales reales, en tus proyectos.",plugins:"Plugins",plugins_sub:"Conecta apps y añade skills; más en el Marketplace.",settings:"Ajustes",settings_sub:"Claves de API, memoria, costes y tu perfil."}},keys:{title:"Añade una clave de API",lede:"Tu asistente necesita una clave de IA para pensar y hablar; sin ella, el chat y la voz siguen apagados. Esta es la página Claves API: pega una clave en la tarjeta de un proveedor y guárdala. Con OpenAI o Gemini basta una sola clave para la voz en directo.",waiting:"Esperando una clave…",connecting:"Activando todo…",connected:"Conectado: {provider}.",present:"Hay una clave guardada. Puedes continuar.",partial:"Algunas partes no cambiaron ({parts}). Puedes arreglarlo más tarde en esta página.",security:"Las claves se guardan en el llavero de tu sistema y solo van al proveedor que elegiste.",later:"Añadiré una clave más tarde"},subscriptions:{title:"Conecta una suscripción para tus agentes",lede:"Esta es la pestaña Agentes. Inicia sesión con una suscripción que ya pagas. Te recomendamos Claude (Pro o Max) o ChatGPT (Codex). Pulsa Connect en su fila; tu navegador se abre una vez.",waiting:"Aún no hay ninguna suscripción conectada…",connected:"Conectado: {names}.",why:"Una suscripción tiene un precio mensual fijo, así las tareas grandes de tus agentes no se cobran por llamada a tu clave de API.",later:"Conectaré una más tarde"},permissions:{title:"Permitir acceso en este Mac",lede:"Estos son los permisos del Mac. Permite los que quieras; cada fila se actualiza sola.",note:"Puedes volver a ellos cuando quieras en Ajustes. El reinicio final los aplica."},voice:{title:"Elige tu palabra de activación",lede:"Escribe aquí tu palabra después de «Hey» y guárdala. La palabra también será el nombre de tu asistente. ¿Sin palabra? El atajo de llamada funciona siempre.",on:"«{phrase}» está activada. Dila cuando quieras.",off:"Aún no hay palabra de activación. Mientras tanto funciona el atajo de llamada.",later:"Omitir, usaré el atajo de llamada"},ready:{title:"Todo listo",lede:"Esto es lo que está configurado. Ahora, una breve visita te enseña la aplicación.",row_brain:"Cerebro",row_agents:"Agentes",row_voice:"Activación",no_subscription:"Sin suscripción",no_key:"Sin clave todavía",shortcut:"Atajo de llamada",autostart:"Iniciar al entrar en la sesión",no_key_note:"Sin clave, el chat y la voz siguen apagados hasta que añadas una en la página Claves API.",preview_note:"Esto es una repetición, así que no se reinicia nada.",restart_note:"Al terminar la visita, la aplicación se reinicia una vez (unos diez segundos) para activarlo todo.",start:"Enséñame la aplicación"}},e={label:"Visita guiada",next:"Siguiente",finish:"Terminar",skip:"Saltar visita",step_of:"{current} de {total}",replay_title:"Configuración y visita guiada",replay_body:"Vuelve a explicar cómo funciona {name}, te guía por la configuración (claves de API, suscripciones de agentes, palabra de activación) y luego por la visita breve de la aplicación. Nada se reinicia.",replay:"Repetir",steps:{voice:"Así hablas con {name}. Haz clic en la barra, di tu palabra de activación o pulsa tu atajo de llamada, y habla. La onda muestra quién está hablando.",new_chat:"¿Prefieres escribir? Empieza aquí un chat nuevo, por texto o por voz. Cada conversación queda en Chats recientes.",agents:"Los agentes son tu equipo: ayudantes que se encargan de trabajos grandes en segundo plano. Echemos un vistazo.",agents_world:"Este es el Verse, tus agentes trabajando. Haz clic en uno para chatear con él o darle una tarea. Siguiente te lleva de vuelta.",voice_hub:"En Voz tienes el dictado en cualquier aplicación, tu propia lista de palabras y atajos hablados.",artifacts:"Todo lo que {name} crea, desde páginas hasta imágenes e informes, se guarda en Artefactos.",ide:"El Agentic IDE ejecuta agentes de programación uno al lado del otro en terminales reales, sobre tus proyectos.",plugins:"Plugins, skills y MCP conectan a {name} con tus aplicaciones. El icono de la tienda, abajo, abre el Marketplace.",settings:"Aquí están los ajustes, las claves de API, los costes y tu perfil. Puedes repetir esta visita cuando quieras en Ajustes → Aplicación.",done:"Esa es la visita. Ya está todo listo: habla con {name} cuando quieras."}},n={title:"Primeros pasos",progress:"{done}/{total}",collapse:"Minimizar",close:"Cerrar",quest_of:"Paso {current} de {total}",how_label:"Cómo funciona:",waiting:"Enviado. Mira el chat: {name} está en ello.",next:"Siguiente paso",finish:"Terminar",skip:"Saltar este",try:{send:"Envíalo por mí",voice:"Abrir el modo de voz",open:"Llévame allí"},show:{memory:"Abrir Notas",artifact:"Abrir Artifacts",agent:"Ver en Agentes"},replay_title:"Primeros pasos con {name}",replay:"Empezar",replay_body:"Diez cosas pequeñas y reales para probar con {name}: hablar, usar herramientas, recordar, construir, pasar trabajo a agentes. Cada una se explica después de ocurrir.",finished:{title:"¡Ya dominas lo básico!",body:"Completaste {done} de {total} primeros pasos. A partir de ahora, simplemente habla con {name}: decide si responde, usa una herramienta o llama a un agente.",close:"Cerrar"},quests:{wake:{title:"Despierta a {name}",ask:"Di tu palabra de activación en voz alta, por ejemplo «Hey {name}». O abre el modo de voz y pulsa el botón redondo de la barra del chat. Después pregunta lo que quieras.",explain:"{name} te escucha. No hace falta más: despiértalo y habla como con una persona.",how:"Tu palabra de activación se reconoce aquí mismo, en tu ordenador. Solo después tu voz va al cerebro, y la respuesta vuelve hablada."},ask:{title:"Haz tu primera pregunta",ask:"Escribe o di una pregunta. Prueba esta:",prompt:"¿Qué puedes hacer por mí? Dame tres ejemplos de mi día a día.",explain:"Ese fue el camino más simple: tus palabras fueron al cerebro y respondió directamente.",how:"El cerebro es el modelo de IA que conectaste. Las preguntas sencillas no necesitan herramientas, así que la respuesta llega en segundos. Cada chat se guarda en Chats recientes."},tool:{title:"Deja que use una herramienta",ask:"Ahora pide algo que necesite sus manos, no solo su cabeza:",prompt:"Abre wikipedia.org en mi navegador.",explain:"Esta vez el cerebro no solo respondió: usó una herramienta para actuar en tu ordenador.",how:"Las herramientas son las manos de {name}. El cerebro elige una, el control de seguridad la aprueba y se ejecuta. Bajo cada respuesta puedes abrir los pasos y ver cada herramienta usada."},screen:{title:"Deja que mire tu pantalla",ask:"{name} puede ver tu pantalla, pero solo cuando lo pides. Prueba:",prompt:"¿Qué hay ahora mismo en mi pantalla? Descríbelo brevemente.",explain:"{name} miró una vez tu pantalla y la describió.",how:"Mirar la pantalla es una sola captura, tomada solo cuando una petición la necesita. Va al cerebro como una foto. Nada graba tu pantalla en segundo plano."},memory:{title:"Enséñale algo",ask:"Cuéntale a {name} algo que valga la pena guardar:",prompt:"Recuerda que mi color favorito es el azul y que prefiero respuestas cortas.",explain:"{name} lo guardó en su memoria y lo usará a partir de ahora.",how:"Los datos van a tu Wiki y a tu perfil, guardados en tu ordenador. Antes de responder, {name} consulta lo que sabe de ti. Puedes leer y editar cada nota en Notas."},artifact:{title:"Haz que cree algo",ask:"{name} puede construir cosas terminadas: páginas, resúmenes, pequeñas herramientas. Di «artifact» para pedir uno:",prompt:"Crea un artifact: un resumen de una página sobre los planetas del sistema solar, con un dato curioso de cada uno.",explain:"{name} empezó a construir la página. Cuando esté lista, aparecerá en Artifacts.",how:"Un artifact es un trabajo más grande, así que {name} se lo pasa a un ayudante con un modelo potente. Construye una página independiente, y Artifacts la guarda para que la abras más tarde."},agent:{title:"Pasa un trabajo grande a un agente",ask:"Para trabajos largos, {name} llama a un agente. Puedes seguir hablando mientras trabaja:",prompt:"Investiga los tres mejores portátiles baratos ahora mismo y escríbeme una comparación corta.",explain:"{name} pasó el trabajo a un agente. Trabaja en segundo plano; el resultado llega a tu chat.",how:"{name} sigue siendo tu único contacto. Planifica el trabajo y pone en marcha un agente, y un revisor comprueba el resultado antes de que te llegue. Puedes ver el progreso en Agentes."},team:{title:"Conoce a tu equipo",ask:"Los agentes son ayudantes con su propio papel. Abre el área Agentes para conocerlos.",explain:"Aquí viven y trabajan tus agentes.",how:"Crea tu propio agente con su papel, modelo e instrucciones, por ejemplo un investigador o una redactora. Haz clic en un agente para chatear con él o darle un encargo. {name} también puede pasarle trabajo por ti."},plugin:{title:"Conecta una app",ask:"Los plugins conectan {name} con las apps que usas: correo, calendario, notas, hogar inteligente y más.",explain:"Aquí conectas tus apps. Elige una que uses a diario y pulsa Conectar; tu navegador se abre una vez para iniciar sesión.",how:"Cada app conectada se convierte en una nueva herramienta para {name}. Después solo pregunta, por ejemplo «¿Qué tengo mañana en el calendario?». Todo lo que envía o cambia algo te pregunta antes."},ide:{title:"Deja que los agentes programen",ask:"El Agentic IDE ejecuta agentes de programación como Claude Code y Codex en terminales reales, en tus propios proyectos.",explain:"Este es el Agentic IDE. Abre una carpeta de proyecto e inicia un agente de programación en un panel.",how:"Cada panel es una terminal real con su propio agente. Háblales escribiendo, o por voz a través de {name}. Varios pueden trabajar lado a lado en el mismo proyecto."}}},s={first_run:a,app_tour:e,first_steps:n};export{e as app_tour,s as default,a as first_run,n as first_steps};
